/* @autogenerated */
package net.civeira.phylax.feature.observe.viewer;

import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.store.ObsLog;
import net.civeira.phylax.feature.observe.store.ObsSpan;
import net.civeira.phylax.feature.observe.store.RetentionPolicy;
import net.civeira.phylax.feature.observe.store.TelemetryQuery;
import net.civeira.phylax.feature.observe.store.TelemetryStore;

class ObserveQueriesTracesUnitTest {

  private static final long NOW = System.currentTimeMillis();

  /** A trace: root GET /orders (100 ms) with a child SELECT orders that matches "select". */
  private static final List<ObsSpan> SPANS = List.of(
      new ObsSpan(NOW - 1_000, "api", "t1", "root", "", "GET /orders", "SERVER", 100, "UNSET",
          Map.of(), null, null),
      new ObsSpan(NOW - 990, "api", "t1", "db", "root", "SELECT orders", "CLIENT", 20, "UNSET",
          Map.of(), null, null),
      new ObsSpan(NOW - 500, "api", "t2", "root2", "", "GET /health", "SERVER", 5, "UNSET",
          Map.of(), null, null));

  /** Store in memory with the same text rule as the JSONL one (name, source, attributes). */
  private static final TelemetryStore STORE = new TelemetryStore() {
    @Override
    public void appendLogs(final List<ObsLog> logs) {}

    @Override
    public void appendSpans(final List<ObsSpan> spans) {}

    @Override
    public List<ObsLog> logs(final TelemetryQuery query) {
      return List.of();
    }

    @Override
    public List<ObsSpan> spans(final TelemetryQuery query) {
      return SPANS.stream()
          .filter(span -> query.getText()
              .map(text -> span.name().toLowerCase().contains(text.toLowerCase())).orElse(true))
          .sorted((a, b) -> Long.compare(b.ts(), a.ts())).collect(Collectors.toList());
    }

    @Override
    public List<ObsSpan> trace(final String traceId, final long from, final long to) {
      return traces(Set.of(traceId), from, to);
    }

    @Override
    public List<ObsSpan> traces(final Set<String> traceIds, final long from, final long to) {
      return SPANS.stream().filter(span -> traceIds.contains(span.traceId()))
          .collect(Collectors.toList());
    }

    @Override
    public void appendPoints(
        final List<net.civeira.phylax.feature.observe.metric.MetricPoint> points) {}

    @Override
    public List<net.civeira.phylax.feature.observe.metric.MetricPoint> points(final long from,
        final long to, final long step, final Set<String> sources) {
      return List.of();
    }

    @Override
    public long sizeBytes() {
      return 0;
    }

    @Override
    public void purge(final RetentionPolicy policy) {}
  };

  private final ObserveQueries queries = new ObserveQueries(STORE, null, null);

  @Test
  @DisplayName("A filter on a child span lists its trace with the real root, duration and spans")
  void summaryOfTheWholeTrace() {
    List<ObserveQueries.TraceSummary> traces =
        queries.traces(Set.of(), "select", false, null, null, null, null, null);
    Assertions.assertEquals(1, traces.size());
    ObserveQueries.TraceSummary trace = traces.get(0);
    Assertions.assertEquals("GET /orders", trace.name());
    Assertions.assertEquals(2, trace.spans());
    Assertions.assertEquals(1, trace.matches());
    Assertions.assertEquals(100.0, trace.durMs(), 0.001);
  }

  @Test
  @DisplayName("The spans view returns only the matching spans, one after the other")
  void spansInSequence() {
    List<ObsSpan> spans = queries.spans(Set.of(), "get", false, null, null, null, null, null);
    Assertions.assertEquals(List.of("GET /health", "GET /orders"),
        spans.stream().map(ObsSpan::name).collect(Collectors.toList()));
  }
}
